import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/architecture/overview.html","title":"架构概述","lang":"en-US","frontmatter":{"title":"架构概述","icon":"architecture","order":1,"category":["架构"],"tag":["架构","概述"]},"filePathRelative":"architecture/overview.md","git":{"createdTime":1773827303000,"updatedTime":1773827303000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),a={name:`overview.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="apollo-架构概述" tabindex="-1"><a class="header-anchor" href="#apollo-架构概述"><span>Apollo 架构概述</span></a></h1><h2 id="整体架构" tabindex="-1"><a class="header-anchor" href="#整体架构"><span>整体架构</span></a></h2><p>Apollo 采用分层模块化架构，共分为 10 层：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                        Applications (apps/)                      │</span>
<span class="line">│  gateway-server | login-server | game-server | chat-server     │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line">                                ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                    Starters (modules/starter/)                  │</span>
<span class="line">│  core | net | mysql | redis | game-server | ...                │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line">                                ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                    BigWorld Compatibility                       │</span>
<span class="line">│                  modules/bigworld/                              │</span>
<span class="line">│  Runtime | Entity | Timer | Callback                            │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line">                                ↓</span>
<span class="line">┌──────┬──────┬──────┬──────┬──────────┬──────────┬────────────┐</span>
<span class="line">│  net │ data │ game │ actor│ framework│  runtime │   core     │</span>
<span class="line">└──────┴──────┴──────┴──────┴──────────┴──────────┴────────────┘</span>
<span class="line">                                ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                        Base (modules/base/)                     │</span>
<span class="line">│  Time | ThreadPool | IdPool | Memory | Terminal | String       │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="层级说明" tabindex="-1"><a class="header-anchor" href="#层级说明"><span>层级说明</span></a></h2><h3 id="level-1-base-modules-base" tabindex="-1"><a class="header-anchor" href="#level-1-base-modules-base"><span>Level 1: Base (<code>modules/base/</code>)</span></a></h3><p>纯基础设施，无框架语义。</p><table><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td>Time</td><td>时间工具、高精度计时</td></tr><tr><td>ThreadPool</td><td>线程池、任务调度</td></tr><tr><td>IdPool</td><td>唯一ID生成器</td></tr><tr><td>ObjectPool</td><td>对象池、内存复用</td></tr><tr><td>String</td><td>字符串处理工具</td></tr><tr><td>Memory</td><td>内存池、Buffer管理</td></tr><tr><td>Terminal</td><td>终端适配、ANSI彩色输出</td></tr></tbody></table><h3 id="level-2-core-modules-core" tabindex="-1"><a class="header-anchor" href="#level-2-core-modules-core"><span>Level 2: Core (<code>modules/core/</code>)</span></a></h3><p>框架内核，公共运行语义。</p><table><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td>DI/IoC</td><td>依赖注入容器</td></tr><tr><td>Config</td><td>配置管理、热更新</td></tr><tr><td>Log</td><td>日志系统、分级输出</td></tr><tr><td>Lifecycle</td><td>应用生命周期管理</td></tr><tr><td>Module</td><td>模块注册与加载</td></tr><tr><td>Event</td><td>事件总线</td></tr><tr><td>Timer</td><td>定时器调度</td></tr><tr><td>ServiceDiscovery</td><td>服务发现</td></tr></tbody></table><h3 id="level-3-runtime-modules-runtime" tabindex="-1"><a class="header-anchor" href="#level-3-runtime-modules-runtime"><span>Level 3: Runtime (<code>modules/runtime/</code>)</span></a></h3><p>宿主运行时，程序如何运行。</p><table><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td>ApplicationHost</td><td>应用宿主</td></tr><tr><td>ServiceHost</td><td>服务宿主</td></tr><tr><td>Console</td><td>控制台输入监听</td></tr><tr><td>Signal</td><td>信号处理 (SIGINT/SIGTERM)</td></tr><tr><td>ShutdownHook</td><td>关闭钩子</td></tr><tr><td>HealthCheck</td><td>健康检查</td></tr></tbody></table><h3 id="level-4-data-modules-data" tabindex="-1"><a class="header-anchor" href="#level-4-data-modules-data"><span>Level 4: Data (<code>modules/data/</code>)</span></a></h3><p>数据访问层。</p><table><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td>core</td><td>数据访问接口</td></tr><tr><td>orm</td><td>ORM映射、数据库操作</td></tr><tr><td>redis</td><td>Redis客户端</td></tr><tr><td>cache</td><td>缓存抽象</td></tr></tbody></table><h3 id="level-5-network-modules-net" tabindex="-1"><a class="header-anchor" href="#level-5-network-modules-net"><span>Level 5: Network (<code>modules/net/</code>)</span></a></h3><p>网络能力层。</p><table><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td>core</td><td>网络抽象接口</td></tr><tr><td>tcp</td><td>TCP通信</td></tr><tr><td>http</td><td>HTTP服务</td></tr><tr><td>websocket</td><td>WebSocket支持</td></tr><tr><td>rpc</td><td>RPC框架</td></tr></tbody></table><h3 id="level-6-actor-modules-actor" tabindex="-1"><a class="header-anchor" href="#level-6-actor-modules-actor"><span>Level 6: Actor (<code>modules/actor/</code>)</span></a></h3><p>Actor 并发模型。</p><table><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td>core</td><td>Actor实体</td></tr><tr><td>timer</td><td>定时器服务</td></tr><tr><td>messaging</td><td>消息总线</td></tr></tbody></table><h3 id="level-7-game-modules-game" tabindex="-1"><a class="header-anchor" href="#level-7-game-modules-game"><span>Level 7: Game (<code>modules/game/</code>)</span></a></h3><p>游戏领域层。</p><table><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td>core</td><td>Entity基类、组件接口</td></tr><tr><td>world</td><td>AOI、场景管理</td></tr><tr><td>battle</td><td>战斗系统、ECS</td></tr><tr><td>attributes</td><td>属性系统</td></tr></tbody></table><h3 id="level-8-bigworld-modules-bigworld" tabindex="-1"><a class="header-anchor" href="#level-8-bigworld-modules-bigworld"><span>Level 8: BigWorld (<code>modules/bigworld/</code>)</span></a></h3><p>BigWorld API 兼容层。</p><h3 id="level-9-starter-modules-starter" tabindex="-1"><a class="header-anchor" href="#level-9-starter-modules-starter"><span>Level 9: Starter (<code>modules/starter/</code>)</span></a></h3><p>装配层，按需组装模块。</p><h3 id="level-10-apps-apps" tabindex="-1"><a class="header-anchor" href="#level-10-apps-apps"><span>Level 10: Apps (<code>apps/</code>)</span></a></h3><p>最终可执行程序。</p><h2 id="依赖关系" tabindex="-1"><a class="header-anchor" href="#依赖关系"><span>依赖关系</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">base ← core ← runtime ← net/data/actor/game ← bigworld ← starter ← apps</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>硬约束</strong>：</p><ul><li>base 不依赖任何 Apollo 模块</li><li>core 不依赖 game/net/data</li><li>game 不反向进入 core</li><li>bigworld 作为 game 的顶层兼容层</li></ul>`,36)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};